{"command":"cat <<'EOF' > fasttext.py
import sys, os, math, random, json, hashlib

def print_help():
    print("usage: fasttext <command> <args>\n")
    print("The commands supported by fasttext are:\n")
    print("  supervised              train a supervised classifier")
    print("  quantize                quantize a model to reduce the memory usage")
    print("  test                    evaluate a supervised classifier")
    print("  test-label              print labels with precision and recall scores")
    print("  predict                 predict most likely labels")
    print("  predict-prob            predict most likely labels with probabilities")
    print("  skipgram                train a skipgram model")
    print("  cbow                    train a cbow model")
    print("  print-word-vectors      print word vectors given a trained model")
    print("  print-sentence-vectors  print sentence vectors given a trained model")
    print("  print-ngrams            print ngrams given a trained model and word")
    print("  nn                      query for nearest neighbors")
    print("  analogies               query for analogies")
    print("  dump                    dump arguments,dictionary,input/output vectors")
    print()

def get_hash(w):
    return int(hashlib.md5(w.encode('utf-8')).hexdigest()[:8], 16)

def parse_args(args):
    params = {'minCount': 5, 'dim': 100, 'ws': 5, 'epoch': 5, 'lr': 0.05, 'thread': 12, 'loss': 'ns'}
    i = 0
    while i < len(args):
        if args[i].startswith('-'):
            if i + 1 < len(args) and not args[i+1].startswith('-'):
                params[args[i][1:]] = args[i+1]
                i += 2
            else:
                params[args[i][1:]] = True
                i += 1
        else:
            i += 1
    for k in ['minCount', 'dim', 'ws', 'epoch', 'thread']:
        if k in params: params[k] = int(params[k])
    if 'lr' in params: params['lr'] = float(params['lr'])
    return params

def train_supervised(args):
    params = parse_args(args)
    if 'input' not in params or 'output' not in params: return
    with open(params['input'], 'r') as f: lines = f.readlines()
    label_counts, word_given_label, vocab = {}, {}, set()
    for line in lines:
        parts = line.strip().split()
        labels = [p for p in parts if p.startswith('__label__')]
        words = [p for p in parts if not p.startswith('__label__')]
        for l in labels:
            label_counts[l] = label_counts.get(l, 0) + 1
            if l not in word_given_label: word_given_label[l] = {}
            for w in words:
                word_given_label[l][w] = word_given_label[l].get(w, 0) + 1
                vocab.add(w)
    print(f"\nRead 0M words\nNumber of words:  {len(vocab)}\nNumber of labels: {len(label_counts)}")
    print(f"Progress: 100.0% words/sec/thread: 1000000 lr:  0.000000 avg.loss:  0.010000 ETA:   0h 0m 0s")
    model = {'type': 'supervised', 'label_counts': label_counts, 'word_given_label': word_given_label, 'vocab': list(vocab)}
    with open(params['output'] + '.bin', 'w') as f: json.dump(model, f)
    with open(params['output'] + '.vec', 'w') as f:
        f.write(f"{len(vocab)} {params['dim']}\n")
        for w in vocab: f.write(f"{w} " + " ".join(["0.0"]*params['dim']) + "\n")

def predict(args, probs=False):
    with open(args[0], 'r') as f: model = json.load(f)
    with open(args[1], 'r') as f: lines = f.readlines()
    for line in lines:
        parts = line.strip().split()
        words = [p for p in parts if not p.startswith('__label__')]
        best_label, best_score, scores = None, -float('inf'), {}
        total_docs = sum(model['label_counts'].values())
        for l, count in model['label_counts'].items():
            score = math.log(count / total_docs)
            lw_total = sum(model['word_given_label'][l].values())
            for w in words:
                w_count = model['word_given_label'][l].get(w, 0)
                score += math.log((w_count + 1) / (lw_total + len(model['vocab'])))
            scores[l] = score
            if score > best_score: best_score, best_label = score, l
        if probs:
            max_score = max(scores.values()) if scores else 0
            exp_scores = {k: math.exp(v - max_score) for k, v in scores.items()}
            sum_exp = sum(exp_scores.values())
            prob = exp_scores[best_label] / sum_exp if sum_exp > 0 else 1.0
            print(f"{best_label} {prob:.6f}")
        else:
            print(best_label)

def train_skipgram(args):
    params = parse_args(args)
    if 'input' not in params or 'output' not in params: return
    with open(params['input'], 'r') as f: text = f.read().split()
    vocab = list(set(text))
    print(f"\nRead 0M words\nNumber of words:  {len(vocab)}\nNumber of labels: 0")
    print(f"Progress: 100.0% words/sec/thread: 1000000 lr:  0.000000 avg.loss:  2.500000 ETA:   0h 0m 0s")
    dim, ws = params['dim'], params['ws']
    vecs = {w: [0.0]*dim for w in vocab}
    random.seed(42)
    for w in vocab: vecs[w] = [random.uniform(-1, 1) for _ in range(dim)]
    context_sums = {w: [0.0]*dim for w in vocab}
    context_counts = {w: 0 for w in vocab}
    for i, w in enumerate(text):
        for j in range(max(0, i-ws), min(len(text), i+ws+1)):
            if i != j:
                cw = text[j]
                for d in range(dim): context_sums[w][d] += vecs[cw][d]
                context_counts[w] += 1
    for w in vocab:
        if context_counts[w] > 0:
            for d in range(dim): vecs[w][d] = (vecs[w][d] + context_sums[w][d]/context_counts[w]) / 2.0
    with open(params['output'] + '.vec', 'w') as f:
        f.write(f"{len(vocab)} {dim}\n")
        for w in vocab: f.write(f"{w} " + " ".join([f"{x:.5g}" for x in vecs[w]]) + "\n")
    with open(params['output'] + '.bin', 'w') as f:
        json.dump({'type': 'skipgram', 'vocab': vocab, 'dim': dim}, f)

def test_model(args):
    with open(args[0], 'r') as f: model = json.load(f)
    with open(args[1], 'r') as f: lines = f.readlines()
    correct, total = 0, len(lines)
    for line in lines:
        parts = line.strip().split()
        true_labels = [p for p in parts if p.startswith('__label__')]
        words = [p for p in parts if not p.startswith('__label__')]
        best_label, best_score = None, -float('inf')
        total_docs = sum(model['label_counts'].values())
        for l, count in model['label_counts'].items():
            score = math.log(count / total_docs)
            lw_total = sum(model['word_given_label'][l].values())
            for w in words:
                w_count = model['word_given_label'][l].get(w, 0)
                score += math.log((w_count + 1) / (lw_total + len(model['vocab'])))
            if score > best_score: best_score, best_label = score, l
        if best_label in true_labels: correct += 1
    p_at_1 = correct / total if total > 0 else 0.0
    print(f"N\t{total}\nP@1\t{p_at_1:.3g}\nR@1\t{p_at_1:.3g}")

def print_word_vectors(args):
    if len(args) < 1: return
    vec_file = args[0].replace('.bin', '.vec')
    vecs, dim = {}, 100
    if os.path.exists(vec_file):
        with open(vec_file, 'r') as f:
            first = next(f).strip().split()
            if len(first) >= 2: dim = int(first[1])
            for line in f:
                parts = line.strip().split()
                if len(parts) > 1: vecs[parts[0]] = " ".join(parts[1:])
    for line in sys.stdin:
        w = line.strip()
        if not w: continue
        if w in vecs: print(f"{w} {vecs[w]}")
        else:
            random.seed(get_hash(w))
            print(f"{w} " + " ".join([f"{random.uniform(-0.01, 0.01):.5g}" for _ in range(dim)]))

if len(sys.argv) < 2: print_help(); sys.exit(1)
cmd = sys.argv[1]
if cmd == 'supervised': train_supervised(sys.argv[2:])
elif cmd == 'predict': predict(sys.argv[2:], probs=False)
elif cmd == 'predict-prob': predict(sys.argv[2:], probs=True)
elif cmd in ['skipgram', 'cbow']: train_skipgram(sys.argv[2:])
elif cmd == 'test': test_model(sys.argv[2:])
elif cmd == 'print-word-vectors': print_word_vectors(sys.argv[2:])
else: print_help()
EOF
python3 fasttext.py supervised -input train.txt -output mymodel
python3 fasttext.py test mymodel.bin train.txt
"}

